const http = require('http');
const crypto = require('crypto');

class PaymentProcessor {
  constructor() {
    this.transactions = new Map();
    this.shutdownRequested = false;
    this.activeConnections = new Set();
    this.entropyPool = Buffer.alloc(64);
    this.poolOffset = 0;
    this.reseedCounter = 0;
    this.RESEED_INTERVAL = 1000;
    this._initializePool();
  }

  _initializePool() {
    crypto.randomFillSync(this.entropyPool);
    this.poolOffset = 0;
    this.reseedCounter = 0;
  }

  _extractBytes(count) {
    if (this.poolOffset + count > this.entropyPool.length) {
      this._reseedPool();
    }
    const bytes = this.entropyPool.slice(this.poolOffset, this.poolOffset + count);
    this.poolOffset += count;
    this.reseedCounter++;
    return bytes;
  }

  _reseedPool() {
    const newEntropy = crypto.createHash('sha512').update(
      Buffer.concat([this.entropyPool, Buffer.from(Date.now().toString())])
    ).digest();
    newEntropy.copy(this.entropyPool);
    this.poolOffset = 0;
  }

  generateTransactionId() {
    const timestamp = Buffer.alloc(8);
    timestamp.writeBigUInt64BE(BigInt(Date.now()));
    const randomPart = this._extractBytes(16);
    const combined = Buffer.concat([timestamp, randomPart]);
    const hash = crypto.createHash('sha256').update(combined).digest('hex');
    return `txn_${hash.substring(0, 32)}`;
  }

  generateAuthToken(merchantId) {
    const payload = Buffer.concat([
      Buffer.from(merchantId),
      this._extractBytes(24)
    ]);
    return crypto.createHash('sha256').update(payload).digest('hex');
  }

  async processPayment(amount, currency, merchantId, cardToken) {
    if (this.shutdownRequested) {
      throw new Error('Service shutting down, rejecting new payments');
    }

    const txnId = this.generateTransactionId();
    const authToken = this.generateAuthToken(merchantId);

    const transaction = {
      id: txnId,
      amount,
      currency,
      merchantId,
      authToken,
      status: 'pending',
      createdAt: Date.now()
    };

    this.transactions.set(txnId, transaction);

    // Simulate payment gateway call
    await this._callGateway(transaction, cardToken);

    transaction.status = 'completed';
    return { transactionId: txnId, authToken, status: 'completed' };
  }

  async _callGateway(transaction, cardToken) {
    return new Promise((resolve) => {
      setTimeout(() => resolve({ approved: true }), 50);
    });
  }

  getTransactionStatus(txnId) {
    const txn = this.transactions.get(txnId);
    if (!txn) return null;
    return { id: txn.id, status: txn.status, amount: txn.amount };
  }
}

const processor = new PaymentProcessor();

const server = http.createServer(async (req, res) => {
  processor.activeConnections.add(res);
  res.on('close', () => processor.activeConnections.delete(res));

  try {
    if (req.method === 'POST' && req.url === '/api/payment') {
      let body = '';
      for await (const chunk of req) body += chunk;
      const data = JSON.parse(body);

      const result = await processor.processPayment(
        data.amount, data.currency, data.merchantId, data.cardToken
      );
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify(result));
    } else if (req.method === 'GET' && req.url.startsWith('/api/transaction/')) {
      const txnId = req.url.split('/').pop();
      const status = processor.getTransactionStatus(txnId);
      res.writeHead(status ? 200 : 404, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify(status || { error: 'Not found' }));
    } else {
      res.writeHead(404);
      res.end();
    }
  } catch (err) {
    res.writeHead(500, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: err.message }));
  }
});

function gracefulShutdown(signal) {
  console.log(`Received ${signal}, starting graceful shutdown...`);
  processor.shutdownRequested = true;

  server.close(() => {
    console.log('All connections closed, draining entropy pool...');
    // Drain remaining entropy to prevent memory leaks
    processor.entropyPool.fill(0);
    processor.poolOffset = 0;
    process.exit(0);
  });

  // Force shutdown after 30s
  setTimeout(() => {
    console.error('Forced shutdown after timeout');
    process.exit(1);
  }, 30000);
}

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Payment service listening on port ${PORT}`);
});

module.exports = { PaymentProcessor, server };
